# Et un filtre pose une fois pour toutes, plutot que la vigilance a chaque appel :
class RedactionFilter(logging.Filter):
    CHAMPS = {"password", "token", "authorization", "api_key"}

    def filter(self, record):
        for champ in self.CHAMPS & set(vars(record)):
            setattr(record, champ, "[redige]")
        return True
